using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using Timarker.Models;using Timarker_WinUI.Services;namespace Timarker_WinUI.Pages;public sealed partial class NotesPage:Page{private NoteItem? _editing;private bool _loading;public NotesPage(){InitializeComponent();Refresh();}private void Refresh(){var q=AppData.Current.Notes.AsEnumerable();var s=SearchBox?.Text?.Trim();if(!string.IsNullOrEmpty(s))q=q.Where(x=>x.Title.Contains(s,StringComparison.CurrentCultureIgnoreCase)||x.Content.Contains(s,StringComparison.CurrentCultureIgnoreCase));NoteList.ItemsSource=q.OrderByDescending(x=>x.IsPinned).ThenByDescending(x=>x.UpdatedAt).ToList();}private void SaveCurrent(){if(_editing is null||_loading)return;_editing.Title=string.IsNullOrWhiteSpace(NoteTitle.Text)?"无标题便签":NoteTitle.Text.Trim();_editing.Content=NoteContent.Text;_editing.UpdatedAt=DateTime.Now;AppData.Current.Save();}private void Add_Click(object s,RoutedEventArgs e){SaveCurrent();var n=new NoteItem{Title="新便签"};AppData.Current.Notes.Add(n);AppData.Current.Save();Refresh();NoteList.SelectedItem=((IEnumerable<NoteItem>)NoteList.ItemsSource).First(x=>x.Id==n.Id);}private void Note_Changed(object s,SelectionChangedEventArgs e){SaveCurrent();_editing=NoteList.SelectedItem as NoteItem;_loading=true;Editor.Visibility=_editing is null?Visibility.Collapsed:Visibility.Visible;if(_editing is not null){NoteTitle.Text=_editing.Title;NoteContent.Text=_editing.Content;PinButton.IsChecked=_editing.IsPinned;}_loading=false;}private void Editor_Changed(object s,TextChangedEventArgs e){if(!_loading)SaveCurrent();}private void Pin_Click(object s,RoutedEventArgs e){if(_editing is null)return;_editing.IsPinned=PinButton.IsChecked==true;SaveCurrent();Refresh();}private async void Delete_Click(object s,RoutedEventArgs e){if(_editing is null)return;var n=_editing;var d=new ContentDialog{XamlRoot=XamlRoot,Title="删除便签？",PrimaryButtonText="删除",CloseButtonText="取消",DefaultButton=ContentDialogButton.Close};if(await d.ShowAsync()!=ContentDialogResult.Primary)return;AppData.Current.Notes.Remove(n);_editing=null;AppData.Current.Save();Editor.Visibility=Visibility.Collapsed;Refresh();}private void Float_Click(object s,RoutedEventArgs e){if(_editing is null)return;SaveCurrent();new FloatingNoteWindow(_editing).Activate();}private void Search_Changed(AutoSuggestBox s,AutoSuggestBoxTextChangedEventArgs e)=>Refresh();}
